'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const N = Number(input[0]);
const M = Number(input[1]);
const grid = Array.from({ length: N }, (_, i) => input[i + 2].split(''));

const queue = new Int32Array(N * M);
let head = 0;
let tail = 0;

for (let r = 0; r < N; r++) {
  for (let c = 0; c < M; c++) {
    if (grid[r][c] === 'o') {
      queue[tail++] = r * M + c;
    }
  }
}

while (head < tail) {
  const pos = queue[head++];
  const r = Math.floor(pos / M);
  const c = pos % M;

  if (r + 1 < N && grid[r + 1][c] === '.') {
    grid[r + 1][c] = 'o';
    queue[tail++] = (r + 1) * M + c;
  }

  if (r + 1 < N && grid[r + 1][c] === '#') {
    if (c > 0 && grid[r][c - 1] === '.') {
      grid[r][c - 1] = 'o';
      queue[tail++] = r * M + c - 1;
    }
    if (c + 1 < M && grid[r][c + 1] === '.') {
      grid[r][c + 1] = 'o';
      queue[tail++] = r * M + c + 1;
    }
  }
}

console.log(grid.map(row => row.join('')).join('\n'));
